        'og_image' => 'https://lettlshelp.com/leadership-systems/assets/og-image.jpg',
        'jsonld' => '{"@context": "https://schema.org", "@graph": [{"@type": "ProfessionalService", "@id": "https://lettlshelp.com/leadership-systems/#organization", "name": "Transformative Leadership Systems", "url": "https://lettlshelp.com/leadership-systems/", "logo": "https://lettlshelp.com/leadership-systems/assets/logo.png", "image": "https://lettlshelp.com/leadership-systems/assets/og-image.jpg", "description": "A private ADR practice providing arbitration, mediation, negotiation support, and conflict coaching for non-consumer-facing businesses, nonprofits, and professional entities.", "telephone": "+1-240-650-0007", "founder": {"@id": "https://lettlshelp.com/leadership-systems/#founder"}, "knowsAbout": ["arbitration", "med-arb", "business mediation", "negotiation", "NDA", "conflict coaching", "ADR", "mediator", "organizational facilitation"], "contactPoint": {"@type": "ContactPoint", "contactType": "customer service", "telephone": "+1-240-650-0007", "availableLanguage": "English", "email": "LeadershipSystems@LetTLSHelp.com"}, "sameAs": ["https://www.facebook.com/LetTLSHelp/", "https://www.linkedin.com/company/lettlshelp"], "email": "LeadershipSystems@LetTLSHelp.com"}, {"@type": "WebSite", "@id": "https://lettlshelp.com/leadership-systems/#website", "url": "https://lettlshelp.com/leadership-systems/", "name": "Transformative Leadership Systems", "inLanguage": "en-US", "publisher": {"@id": "https://lettlshelp.com/leadership-systems/#organization"}}, {"@type": ["WebPage", "FAQPage"], "@id": "https://lettlshelp.com/leadership-systems/faq/#webpage", "url": "https://lettlshelp.com/leadership-systems/faq/", "name": "Arbitration FAQ | Transformative Leadership Systems", "description": "Answers about arbitration, med-arb, business mediation, NDAs, eligibility, confidentiality, and getting started with Transformative Leadership Systems.", "inLanguage": "en-US", "isPartOf": {"@id": "https://lettlshelp.com/leadership-systems/#website"}, "about": {"@id": "https://lettlshelp.com/leadership-systems/#organization"}, "mainEntity": [{"@type": "Question", "name": "What services does Transformative Leadership Systems offer?", "acceptedAnswer": {"@type": "Answer", "text": "Arbitration and med-arb (business-to-business only), business and organizational mediation, negotiation support, and conflict coaching for leaders."}}, {"@type": "Question", "name": "What is the difference between mediation, arbitration, and med-arb?", "acceptedAnswer": {"@type": "Answer", "text": "In mediation, a neutral helps the parties reach their own agreement. In arbitration, a neutral hears each side and issues a decision that may be binding or non-binding, depending on what the parties agree to. Med-arb combines the two: mediation first, then arbitration for any issues that remain."}}, {"@type": "Question", "name": "Who is eligible?", "acceptedAnswer": {"@type": "Answer", "text": "Non-consumer-facing business owners, nonprofit organizations, and professional entities. Typical matters include internal workplace disputes, leadership and partnership conflicts, board governance issues, and vendor–supplier disputes between non-consumer-facing entities."}}, {"@type": "Question", "name": "Can you help with NDAs or other business contracts?", "acceptedAnswer": {"@type": "Answer", "text": "Negotiation support includes contract interpretation for non-consumer agreements and inter-organizational communication. We remain neutral and do not provide legal advice, so each party may wish to consult its own attorney."}}, {"@type": "Question", "name": "Do you work with consumer-facing companies?", "acceptedAnswer": {"@type": "Answer", "text": "No. If your matter involves a consumer transaction, or if you are a consumer‑facing company or organization, Transformative Leadership Systems cannot assist due to statutory ethics requirements under Maryland Public Ethics Law §5‑502."}}, {"@type": "Question", "name": "Do you provide legal advice?", "acceptedAnswer": {"@type": "Answer", "text": "No. We provide neutral ADR services only. We do not provide legal advice, legal representation, or legal advocacy."}}, {"@type": "Question", "name": "Is this counseling or therapy?", "acceptedAnswer": {"@type": "Answer", "text": "No. We provide conflict-coaching and organizational facilitation services only. We do not provide medical or mental health counseling or clinical therapeutic services."}}, {"@type": "Question", "name": "Is the process confidential?", "acceptedAnswer": {"@type": "Answer", "text": "All mediation‑related communication will remain confidential in accordance with applicable ADR confidentiality standards."}}, {"@type": "Question", "name": "What happens if my matter isn\'t eligible?", "acceptedAnswer": {"@type": "Answer", "text": "We use written and verbal screening to determine eligibility and document every screening decision. If we are unable to facilitate your matter, we will provide free supportive referrals."}}, {"@type": "Question", "name": "Do you meet virtually or in person?", "acceptedAnswer": {"@type": "Answer", "text": "Both. We serve eligible B2B clients with virtual and in-person options."}}, {"@type": "Question", "name": "Do you handle family or personal conflicts?", "acceptedAnswer": {"@type": "Answer", "text": "Family, parenting, and interpersonal matters are handled by our sister practice, Transformative Life Solutions."}}, {"@type": "Question", "name": "How do I get started?", "acceptedAnswer": {"@type": "Answer", "text": "Complete our online screening, email LeadershipSystems@LetTLSHelp.com, or call or text (240) 650-0007."}}, {"@type": "Question", "name": "How much do arbitration, mediation, and negotiation support cost?", "acceptedAnswer": {"@type": "Answer", "text": "Fees depend on the process, the number of parties, and the time involved. We confirm pricing after screening, before anything is scheduled."}}, {"@type": "Question", "name": "Who pays for the process?", "acceptedAnswer": {"@type": "Answer", "text": "Organizations commonly share the cost, though the parties can agree on a different split, and a contract clause may already say who pays."}}, {"@type": "Question", "name": "How long does a business mediation or arbitration take?", "acceptedAnswer": {"@type": "Answer", "text": "It depends on the complexity of the dispute, the number of parties, and how much documentation is involved. We give you an estimate after screening."}}, {"@type": "Question", "name": "What happens in the first session?", "acceptedAnswer": {"@type": "Answer", "text": "We confirm the process the parties have agreed to, set ground rules and confidentiality expectations, identify the issues in dispute, and agree on what information is needed to move forward."}}, {"@type": "Question", "name": "Is an arbitration award binding?", "acceptedAnswer": {"@type": "Answer", "text": "That depends on what the parties agreed to. We offer binding, non-binding, and hybrid processes, so the agreement or contract clause that brings you to arbitration determines the effect of the outcome."}}, {"@type": "Question", "name": "What is a mediation or arbitration clause in a contract?", "acceptedAnswer": {"@type": "Answer", "text": "It is a term in a business agreement saying that if a dispute arises, the parties will use mediation or arbitration rather than going straight to court. If your contract already has one, bring it to screening so we can confirm the process it requires."}}, {"@type": "Question", "name": "How is arbitration different from going to court?", "acceptedAnswer": {"@type": "Answer", "text": "Arbitration is private, generally faster, and scheduled around the parties rather than a court docket, and the parties choose their neutral. Court proceedings are public and follow the court\'s rules and calendar."}}, {"@type": "Question", "name": "Can you help with a partnership dispute or a board conflict?", "acceptedAnswer": {"@type": "Answer", "text": "Yes, for eligible non-consumer-facing organizations. We work with internal workplace disputes, leadership and partnership conflicts, board governance issues, and vendor–supplier disputes between non-consumer-facing entities."}}], "breadcrumb": {"@id": "https://lettlshelp.com/leadership-systems/faq/#breadcrumb"}}, {"@type": "Person", "@id": "https://lettlshelp.com/leadership-systems/#founder", "name": "Tanika L. Smith", "jobTitle": "Founder", "worksFor": {"@id": "https://lettlshelp.com/leadership-systems/#organization"}}, {"@type": "BreadcrumbList", "@id": "https://lettlshelp.com/leadership-systems/faq/#breadcrumb", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "Home", "item": "https://lettlshelp.com/leadership-systems/"}, {"@type": "ListItem", "position": 2, "name": "FAQ", "item": "https://lettlshelp.com/leadership-systems/faq/"}]}]}',
    ),
