    '/life-solutions/faq/' => array(
        'title' => 'Mediation FAQ | Transformative Life Solutions',
        'description' => 'Answers about divorce mediation, parenting plans, confidentiality, eligibility, legal advice, and how to get started with Transformative Life Solutions.',
        'og_image' => 'https://lettlshelp.com/life-solutions/assets/og-image.jpg',
        'jsonld' => '{"@context": "https://schema.org", "@graph": [{"@type": "ProfessionalService", "@id": "https://lettlshelp.com/life-solutions/#organization", "name": "Transformative Life Solutions", "url": "https://lettlshelp.com/life-solutions/", "logo": "https://lettlshelp.com/life-solutions/assets/logo.png", "image": "https://lettlshelp.com/life-solutions/assets/og-image.jpg", "description": "A private ADR, mediation, and conflict coaching practice offering trauma-informed, culturally grounded support for families, individuals, and non-consumer-facing workplaces.", "telephone": "+1-240-650-0007", "founder": {"@id": "https://lettlshelp.com/life-solutions/#founder"}, "knowsAbout": ["mediation", "mediator", "divorce mediation", "separation agreement", "parenting plan", "prenuptial agreement", "conflict coaching", "ADR", "alternative dispute resolution"], "contactPoint": {"@type": "ContactPoint", "contactType": "customer service", "telephone": "+1-240-650-0007", "availableLanguage": "English", "email": "LifeSolutions@LetTLSHelp.com"}, "sameAs": ["https://www.facebook.com/LetTLSHelp/", "https://www.linkedin.com/company/lettlshelp"], "email": "LifeSolutions@LetTLSHelp.com"}, {"@type": "WebSite", "@id": "https://lettlshelp.com/life-solutions/#website", "url": "https://lettlshelp.com/life-solutions/", "name": "Transformative Life Solutions", "inLanguage": "en-US", "publisher": {"@id": "https://lettlshelp.com/life-solutions/#organization"}}, {"@type": ["WebPage", "FAQPage"], "@id": "https://lettlshelp.com/life-solutions/faq/#webpage", "url": "https://lettlshelp.com/life-solutions/faq/", "name": "Mediation FAQ | Transformative Life Solutions", "description": "Answers about divorce mediation, parenting plans, confidentiality, eligibility, legal advice, and how to get started with Transformative Life Solutions.", "inLanguage": "en-US", "isPartOf": {"@id": "https://lettlshelp.com/life-solutions/#website"}, "about": {"@id": "https://lettlshelp.com/life-solutions/#organization"}, "mainEntity": [{"@type": "Question", "name": "What services does Transformative Life Solutions offer?", "acceptedAnswer": {"@type": "Answer", "text": "Family and parenting mediation, interpersonal mediation, workplace and organizational facilitation for non-consumer-facing organizations, and one-on-one conflict coaching."}}, {"@type": "Question", "name": "Do you offer divorce mediation and help with parenting plans?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. Family and parenting mediation supports separation, parenting plans, co-parenting communication, and family transitions."}}, {"@type": "Question", "name": "Can mediation help with a separation agreement or prenuptial agreement?", "acceptedAnswer": {"@type": "Answer", "text": "Mediation can help both people talk through the terms they want to reach. We do not provide legal advice or representation, so you may wish to have your own attorney review any agreement."}}, {"@type": "Question", "name": "Do you provide legal advice?", "acceptedAnswer": {"@type": "Answer", "text": "No. Transformative Life Solutions provides mediation services only. We do not provide legal advice, legal representation, or legal advocacy."}}, {"@type": "Question", "name": "Is this counseling or therapy?", "acceptedAnswer": {"@type": "Answer", "text": "No. We provide coaching and training services only. We do not provide medical or mental health counseling services."}}, {"@type": "Question", "name": "Is mediation confidential?", "acceptedAnswer": {"@type": "Answer", "text": "In accordance with the Maryland Mediation and Confidentiality Act, all mediation-related communication will remain confidential. The full statement, with both wordings, is on the Disclaimers page."}}, {"@type": "Question", "name": "What matters do you not handle?", "acceptedAnswer": {"@type": "Answer", "text": "We do not handle consumer-business disputes (such as refunds, billing, purchases, warranties, or service agreements), auto sales or repair disputes, home improvement or contractor disputes, housing disputes, or any matter connected to Maryland consumer protection laws or the Office of the Attorney General."}}, {"@type": "Question", "name": "What happens if my matter isn\'t a fit?", "acceptedAnswer": {"@type": "Answer", "text": "We use written and verbal screening to determine eligibility. If we are unable to facilitate your matter, we will provide free supportive referrals."}}, {"@type": "Question", "name": "Do you meet virtually or in person?", "acceptedAnswer": {"@type": "Answer", "text": "Both. We serve clients with virtual and in-person options."}}, {"@type": "Question", "name": "Do you offer arbitration, negotiation support, or help with NDAs?", "acceptedAnswer": {"@type": "Answer", "text": "Arbitration, med-arb, and negotiation support for eligible, non-consumer-facing organizations are offered through our sister practice, Transformative Leadership Systems."}}, {"@type": "Question", "name": "How do I get started?", "acceptedAnswer": {"@type": "Answer", "text": "Complete our online screening, email LifeSolutions@LetTLSHelp.com, or call or text (240) 650-0007."}}, {"@type": "Question", "name": "How much does mediation cost?", "acceptedAnswer": {"@type": "Answer", "text": "Fees depend on the service and the time involved. We confirm pricing with you after screening, before any session is scheduled."}}, {"@type": "Question", "name": "How long does mediation take?", "acceptedAnswer": {"@type": "Answer", "text": "It depends on the number of issues and how prepared both people are. We give you an estimate after screening."}}, {"@type": "Question", "name": "What happens in a first mediation session?", "acceptedAnswer": {"@type": "Answer", "text": "The mediator explains the process and ground rules, each person describes what matters most to them, and together you set an agenda for the issues to work through."}}, {"@type": "Question", "name": "Do both people have to agree to mediation?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. All parties must agree to participate, unless an order requires it. If the other person has not agreed yet, you can still complete the screening and we will discuss next steps."}}, {"@type": "Question", "name": "Do I still need a lawyer if we mediate?", "acceptedAnswer": {"@type": "Answer", "text": "We provide mediation only and do not give legal advice or representation, so many people choose to get independent legal advice about their options and to review anything they sign. Whether you need a lawyer is your decision."}}, {"@type": "Question", "name": "Is a mediated agreement legally binding?", "acceptedAnswer": {"@type": "Answer", "text": "Mediation helps you and the other person reach terms you both accept. Whether those terms become legally enforceable depends on how they are written, signed, and, in some matters, submitted to a court. Because we do not provide legal advice, you may wish to have your own attorney review any agreement."}}, {"@type": "Question", "name": "What if there has been abuse, violence, or safety concerns?", "acceptedAnswer": {"@type": "Answer", "text": "Tell us during screening. We ask directly about threats, violence, harassment, and coercive control. Depending on the circumstances we may still be able to help, may suggest a different structure, or may refer you elsewhere. If you are in immediate danger, call 911."}}, {"@type": "Question", "name": "How does divorce or separation mediation work?", "acceptedAnswer": {"@type": "Answer", "text": "Instead of arguing positions through others, both people meet with a neutral mediator to talk through the decisions a separation requires, such as parenting time, communication, and next steps. You control the outcome; the mediator manages the conversation and keeps it balanced."}}, {"@type": "Question", "name": "What is a parenting plan?", "acceptedAnswer": {"@type": "Answer", "text": "A parenting plan is a written arrangement covering how co-parents share time, make decisions, handle holidays and exchanges, and communicate with each other. Mediation gives both parents a structured way to build one together."}}], "breadcrumb": {"@id": "https://lettlshelp.com/life-solutions/faq/#breadcrumb"}}, {"@type": "Person", "@id": "https://lettlshelp.com/life-solutions/#founder", "name": "Tanika L. Smith", "jobTitle": "Founder", "worksFor": {"@id": "https://lettlshelp.com/life-solutions/#organization"}}, {"@type": "BreadcrumbList", "@id": "https://lettlshelp.com/life-solutions/faq/#breadcrumb", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "Home", "item": "https://lettlshelp.com/life-solutions/"}, {"@type": "ListItem", "position": 2, "name": "FAQ", "item": "https://lettlshelp.com/life-solutions/faq/"}]}]}',
    ),
